"},"$:/config/HighlightPlugin/TypeMappings/":{"title":"$:/config/HighlightPlugin/TypeMappings/","type":"text/vnd.tiddlywiki","text":"tw"},"$:/config/HighlightPlugin/TypeMappings/text/vnd.tiddlywiki":{"title":"$:/config/HighlightPlugin/TypeMappings/text/vnd.tiddlywiki","type":"text/vnd.tiddlywiki","text":"tw"},"$:/plugins/tiddlywiki/highlight/highlight.css":{"title":"$:/plugins/tiddlywiki/highlight/highlight.css","tags":"$:/tags/Stylesheet $:/tags/Stylesheet/Highlight","type":"text/css","text":"/*
  Theme: Base Reactive Fallback
  Description: Handles base element reset and "catch-all" classes missed by the specific /styles sheet.
*/

/* 1. RESET & BASE STRUCTURE */
        pre code.hljs {
        display: block;
        /* Allow horizontal scrolling for long lines, but hide vertical scrollbars */
        overflow-x: auto;
        overflow-y: hidden;
        /* Remove any default constraints so it grows with content */
        max-height: none;
        padding: 1em;
    }

    code.hljs {
        padding: 3px 5px;
    }

    /* 2. MAIN CONTAINER DEFAULT */
    /* Matches your /styles preference, ensuring safety if /styles is disabled */
    .hljs {
        background: var(--lithic-c-code-bg);
        color: var(--lithic-c-code-fg);
    }

    /* 3. CRITICAL MISSING ELEMENTS (Not in your /styles) */

    /* Punctuation & Tags: 
   These are missing from your /styles. 
   We map them to 'foreground' so they are visible but neutral. 
*/
    .hljs-punctuation,
    .hljs-tag {
        color: var(--lithic-c-code-ref);
    }

    /* Operators: 
   Missing from your /styles. 
   Original highlight.js groups these with 'links/symbols'. 
   We map them to 'tag-background' to match your 'Symbols' logic.
*/
    .hljs-operator {
        color: var(--lithic-c-code-warn);
    }

    /* Tag Names & Attributes:
   Usually handled by 'keyword' or 'title', but explicit 'tag' children need care.
   Map to Primary to match Keywords.
*/
    .hljs-tag .hljs-name,
    .hljs-tag .hljs-attr {
        color: var(--lithic-c-code-accent);
    }

    /* 4. FALLBACKS FOR INLINE CODE */
    .hljs-code {
        color: var(--lithic-c-code-fg);
    }"},"$:/plugins/tiddlywiki/highlight/styles":{"title":"$:/plugins/tiddlywiki/highlight/styles","tags":"$:/tags/Stylesheet $:/tags/Stylesheet/Highlight","type":"text/css","text":"/*
Syntax colouring via the lithic contrast core (--lithic-c-*): every colour
is derived from the live palette with WCAG contrast targets, so no palette
can make these muddy. The lithic-contrast publisher always defines the
variables. Role semantics (see $:/plugins/xyvir/lithic-core/contrast.js):
  code-fg     neutral text / titles        code-accent  keywords (brand hue)
  code-ref    strings & neutral refs       code-warn    numbers, symbols, meta
*/

.hljs {
    background: var(--lithic-c-code-bg);
    color: var(--lithic-c-code-fg);
    border: 1px solid var(--lithic-c-code-border);
    padding: 0.5em;
    border-radius: 2px;
    display: block;
    overflow-x: auto;
}

/* COMMENTS: muted neutral */
.hljs-comment,
.hljs-quote {
    color: var(--lithic-c-code-ref);
    font-style: italic;
}

/* KEYWORDS: brand accent */
.hljs-keyword,
.hljs-selector-tag,
.hljs-addition {
    color: var(--lithic-c-code-accent);
    font-weight: bold;
}

/* STRINGS & LITERALS: neutral ref tone */
.hljs-string,
.hljs-meta .hljs-string,
.hljs-literal,
.hljs-doctag,
.hljs-regexp {
    color: var(--lithic-c-code-ref);
}

/* NUMBERS: secondary accent */
.hljs-number {
    color: var(--lithic-c-code-warn);
}

/* TITLES & SECTIONS: base text, bolded */
.hljs-title,
.hljs-section,
.hljs-name,
.hljs-selector-id,
.hljs-selector-class {
    color: var(--lithic-c-code-fg);
    font-weight: bold;
}

/* VARIABLES & ATTRIBUTES: brand accent (regular weight) */
.hljs-attribute,
.hljs-attr,
.hljs-variable,
.hljs-template-variable,
.hljs-class .hljs-title,
.hljs-type {
    color: var(--lithic-c-code-accent);
}

/* META & SYMBOLS: secondary accent */
.hljs-symbol,
.hljs-bullet,
.hljs-subst,
.hljs-meta,
.hljs-meta .hljs-keyword,
.hljs-selector-attr,
.hljs-selector-pseudo,
.hljs-link {
    color: var(--lithic-c-code-warn);
}

/* BUILTINS & DIFF DELETIONS: secondary accent */
.hljs-built_in,
.hljs-deletion {
    color: var(--lithic-c-code-warn);
}

/* EMPHASIS & STRONG */
.hljs-emphasis {
    font-style: italic;
}

.hljs-strong {
    font-weight: bold;
}"},"$:/plugins/xyvir/lithic-wikitext-highlight/wikitext-highlighter.js":{"title":"$:/plugins/xyvir/lithic-wikitext-highlight/wikitext-highlighter.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/plugins/xyvir/lithic-wikitext-highlight/wikitext-highlighter.js
type: application/javascript
module-type: startup

Starts up the wikitext highlighter
\*/
(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    exports.name = "wikitext-highlighter";
    exports.platforms = ["browser"];
    exports.after = ["startup"];
    exports.synchronous = true;

    exports.startup = function () {
        if ($tw.browser && !window.hljs) {
            try {
                window.hljs = require("$:/plugins/tiddlywiki/highlight/highlight.js");
            } catch (e) { return; }
        }

        var hljs = window.hljs || require("$:/plugins/tiddlywiki/highlight/highlight.js");
        if (!hljs) return;

        hljs.registerLanguage('tw', function (hljs) {
            return {
                name: 'Wikitext',
                aliases: ['wikitext'],
                contains: [
                    // --- NEW: PRAGMAS (\procedure, \define, etc) ---
                    {
                        className: 'keyword',
                        begin: /^\\([a-zA-Z0-9\-\.]+)/,
                        end: /$/
                    },

                    // --- NEW: HEADERS (! Header) ---
                    {
                        className: 'section',
                        begin: /^!/,
                        end: /$/
                    },

                    // --- NEW: CLOSING WIDGETS (</$button>) ---
                    {
                        className: 'tag',
                        begin: /<\/\$[a-zA-Z0-9\-\.]+>/
                    },

                    // 1. BLOCK MACROS <<<...>>> (Moved to top priority)
                    {
                        className: 'quote',
                        begin: /^<<<+/, end: />>>+$/
                    },

                    // 2. WIDGETS <$button ...> 
                    {
                        className: 'tag',
                        begin: /<\$[a-zA-Z0-9\-\.]+/,
                        end: />/,
                        contains: [
                            hljs.QUOTE_STRING_MODE,
                            // Allow macros inside widget attributes
                            {
                                className: 'symbol',
                                begin: /<<+/, end: />>+/
                            }
                        ]
                    },

                    // 3. INLINE MACROS <<...>>
                    {
                        className: 'symbol',
                        begin: /<<+/, end: />>+/
                    },

                    // 4. FORMATTING
                    {
                        className: 'strong',
                        begin: /''/, end: /''/
                    },
                    {
                        className: 'emphasis',
                        begin: /\/\//, end: /\/\//
                    },

                    // 5. WIKI LINKS [[...]]
                    {
                        className: 'link',
                        begin: /\[\[/, end: /\]\]/
                    },

                    // 6. TEMPLATES {{...}}
                    {
                        className: 'template-variable',
                        begin: /\{\{/, end: /\}\}/
                    },

                    // 7. GENERIC BRACKETS
                    {
                        className: 'meta',
                        begin: /[\[\]]/
                    },

                    // 8. STANDARD STRINGS
                    hljs.QUOTE_STRING_MODE
                ]
            };
        });

        hljs.registerLanguage('matlab', function(hljs) {
          const TRANSPOSE_RE = '(\'|\\.\')+';
          const TRANSPOSE = {
            relevance: 0,
            contains: [ { begin: TRANSPOSE_RE } ]
          };

          return {
            name: 'Matlab',
            aliases: ['octave'],
            keywords: {
              keyword:
                'arguments break case catch classdef continue else elseif end enumeration events for function '
                + 'global if methods otherwise parfor persistent properties return spmd switch try while',
              built_in:
                'sin sind sinh asin asind asinh cos cosd cosh acos acosd acosh tan tand tanh atan '
                + 'atand atan2 atanh sec secd sech asec asecd asech csc cscd csch acsc acscd acsch cot '
                + 'cotd coth acot acotd acoth hypot exp expm1 log log1p log10 log2 pow2 realpow reallog '
                + 'realsqrt sqrt nthroot nextpow2 abs angle complex conj imag real unwrap isreal '
                + 'cplxpair fix floor ceil round mod rem sign airy besselj bessely besselh besseli '
                + 'besselk beta betainc betaln ellipj ellipke erf erfc erfcx erfinv expint gamma '
                + 'gammainc gammaln psi legendre cross dot factor isprime primes gcd lcm rat rats perms '
                + 'nchoosek factorial cart2sph cart2pol pol2cart sph2cart hsv2rgb rgb2hsv zeros ones '
                + 'eye repmat rand randn linspace logspace freqspace meshgrid accumarray size length '
                + 'ndims numel disp isempty isequal isequalwithequalnans cat reshape diag blkdiag tril '
                + 'triu fliplr flipud flipdim rot90 find sub2ind ind2sub bsxfun ndgrid permute ipermute '
                + 'shiftdim circshift squeeze isscalar isvector ans eps realmax realmin pi i|0 inf nan '
                + 'isnan isinf isfinite j|0 why compan gallery hadamard hankel hilb invhilb magic pascal '
                + 'rosser toeplitz vander wilkinson max min nanmax nanmin mean nanmean type table '
                + 'readtable writetable sortrows sort figure plot plot3 scatter scatter3 cellfun '
                + 'legend intersect ismember procrustes hold num2cell '
            },
            illegal: '(//|"|#|/\\*|\\s+/\\w+)',
            contains: [
              {
                className: 'function',
                beginKeywords: 'function',
                end: '$',
                contains: [
                  hljs.UNDERSCORE_TITLE_MODE,
                  {
                    className: 'params',
                    variants: [
                      {
                        begin: '\\(',
                        end: '\\)'
                      },
                      {
                        begin: '\\[',
                        end: '\\]'
                      }
                    ]
                  }
                ]
              },
              {
                className: 'built_in',
                begin: /true|false/,
                relevance: 0,
                starts: TRANSPOSE
              },
              {
                begin: '[a-zA-Z][a-zA-Z_0-9]*' + TRANSPOSE_RE,
                relevance: 0
              },
              {
                className: 'symbol',
                begin: /\[/,
                end: /\]/,
                contains: [
                  'self',
                  {
                    className: 'number',
                    begin: /(-?)(\b0[xX][a-fA-F0-9]+|(\b\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?)/,
                    relevance: 0,
                    starts: TRANSPOSE
                  },
                  {
                    className: 'string',
                    begin: '\'',
                    end: '\'',
                    contains: [ { begin: '\'\'' } ]
                  },
                  {
                    className: 'string',
                    begin: '"',
                    end: '"',
                    contains: [ { begin: '""' } ]
                  }
                ],
                relevance: 0
              },
              {
                className: 'number',
                begin: /(-?)(\b0[xX][a-fA-F0-9]+|(\b\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?)/,
                relevance: 0,
                starts: TRANSPOSE
              },
              {
                className: 'string',
                begin: '\'',
                end: '\'',
                contains: [ { begin: '\'\'' } ]
              },
              {
                begin: /\]|\}|\)/,
                relevance: 0,
                starts: TRANSPOSE
              },
              {
                className: 'string',
                begin: '"',
                end: '"',
                contains: [ { begin: '""' } ],
                starts: TRANSPOSE
              },
              hljs.COMMENT('^\\s*%\\{\\s*$', '^\\s*%\\}\\s*$'),
              hljs.COMMENT('%', '$')
            ]
          };
        });

        // Register jspython as an alias for python
        if (typeof hljs.registerAliases === "function") {
            try {
                hljs.registerAliases('jspython', {languageName: 'python'});
            } catch (e) {}
        } else {
            var py = hljs.getLanguage('python');
            if (py) {
                hljs.registerLanguage('jspython', function() { return py; });
            }
        }

    };

})();"}}}
